  Lemma ro_poison_word : forall mm, mem_inv asegs mm -> ro_cells asegs mm 66624 [C8 (Z_to_bv 64 0xaaaaaaaaaaaaaaaa)].
  Proof.
    intros mm MIx.
    pose proof (ro_cells_image asegs mm 66624 (le8 (Z_to_bv 64 0xaaaaaaaaaaaaaaaa)) MIx ltac:(vm_compute; reflexivity) ltac:(lia) ltac:(cbn; lia)) as R.
    destruct R as [WF B]. split; [cbn; split; [reflexivity| exact I]|]. cbn [cells_bytes cbytes] in B |- *. exact B.
  Qed.

